{
  "components": [
    {
      "type": "claim",
      "quote": "With the Energy Strategy more money is available from the CO2 levy for the Building Programme.",
      "gist": "More CO2 levy funds are allocated to the Building Programme under the Energy Strategy."
    },
    {
      "type": "claim",
      "quote": "Tax incentives for building renovation",
      "gist": "Tax incentives exist for building renovation."
    },
    {
      "type": "claim",
      "quote": "Investments carried out in buildings to improve energy efficiency are already tax-deductible today.",
      "gist": "Energy efficiency investments in buildings are currently tax-deductible."
    },
    {
      "type": "claim",
      "quote": "With the implementation of new Energy Act, it is now also possible to deduct the costs of demolition to make way for a new building.",
      "gist": "The new Energy Act allows tax deduction for demolition costs to build new structures."
    },
    {
      "type": "condition",
      "quote": "if it is not possible to fully offset the expenditure in the year in which it was carried out.",
      "gist": "If demolition and energy-related costs cannot be fully deducted in the year incurred."
    },
    {
      "type": "obligation",
      "quote": "demolition costs can be deducted also in the next two tax periods",
      "gist": "Demolition costs may be deducted over the next two tax periods."
    }
  ]
}
